def normalize_phone(p):
    digits = "".join(ch for ch in p if ch.isdigit())
    if p.strip().startswith("+"):
        return "+" + digits
    return digits

reference_solution.utils/text.py:
def slugify(title):
    out = []
    for ch in title.lower():
        if ch.isalnum():
            out.append(ch)
        elif ch == " ":
            out.append("-")
    return "".join(out)

def truncate(s, n):
    if len(s) <= n:
        return s
    return s[:n] + "…"

